    <!-- Fonts: Neon Cyber style - techy, confident -->
    <link rel="stylesheet" href="https://api.fontshare.com/v2/css?f[]=clash-display@700,600&f[]=satoshi@400,500,700&display=swap">

    <style>
        /* ===========================================
           CSS CUSTOM PROPERTIES (THEME)
           Neon Cyber aesthetic - deep navy, cyan/magenta accents
           =========================================== */
        :root {
            --bg-primary: #0a0f1c;
            --bg-secondary: #111827;
            --bg-card: #1a2332;
            --text-primary: #ffffff;
            --text-secondary: #9ca3af;
            --accent-cyan: #00ffcc;
            --accent-magenta: #ff00aa;
            --accent-blue: #4361ee;
            --accent-orange: #ff6b35;
