            --accent-green: #22c55e;

            /* Typography - MUST use clamp() */
            --font-display: 'Clash Display', sans-serif;
            --font-body: 'Satoshi', sans-serif;
            --title-size: clamp(1.75rem, 5vw, 3.5rem);
            --h2-size: clamp(1.25rem, 3.5vw, 2.25rem);
            --h3-size: clamp(1rem, 2vw, 1.5rem);
            --body-size: clamp(0.75rem, 1.3vw, 1.1rem);
            --small-size: clamp(0.65rem, 1vw, 0.875rem);

            /* Spacing - MUST use clamp() */
            --slide-padding: clamp(1.5rem, 4vw, 4rem);
            --content-gap: clamp(1rem, 2vw, 2rem);
            --element-gap: clamp(0.5rem, 1vw, 1rem);

            /* Animation */
            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
            --duration-normal: 0.6s;
        }

        /* ===========================================
           BASE STYLES
           =========================================== */
        * { margin: 0; padding: 0; box-sizing: border-box; }

        html {
            scroll-snap-type: y mandatory;
            scroll-behavior: smooth;
        }

        body {
            font-family: var(--font-body);
            background: var(--bg-primary);
            color: var(--text-primary);
            line-height: 1.4;
        }

        /* ===========================================
           VIEWPORT FITTING: MANDATORY BASE STYLES
           =========================================== */
        html, body {
            height: 100%;
            overflow-x: hidden;
        }

        .slide {
            width: 100vw;
            width: 100dvw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
        }

        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            overflow: hidden;
            padding: var(--slide-padding);
        }

        /* ===========================================
           ANIMATIONS
           =========================================== */
        .reveal {
            opacity: 0;
            transform: translateY(30px);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }

        .slide.visible .reveal {
            opacity: 1;
            transform: translateY(0);
        }

        .reveal:nth-child(1) { transition-delay: 0.1s; }
        .reveal:nth-child(2) { transition-delay: 0.2s; }
        .reveal:nth-child(3) { transition-delay: 0.3s; }
        .reveal:nth-child(4) { transition-delay: 0.4s; }
        .reveal:nth-child(5) { transition-delay: 0.5s; }

        /* ===========================================
           NEON CYBER THEME STYLES
           =========================================== */

        /* Background gradient mesh */
        .gradient-bg {
            background:
                radial-gradient(ellipse at 20% 80%, rgba(0, 255, 204, 0.15) 0%, transparent 50%),
                radial-gradient(ellipse at 80% 20%, rgba(255, 0, 170, 0.1) 0%, transparent 50%),
                var(--bg-primary);
        }

        /* Grid pattern overlay */
        .grid-bg {
            background-image:
                linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),
                linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px);
            background-size: 50px 50px;
        }

        /* Neon glow effect */
        .neon-glow {
            box-shadow: 0 0 30px rgba(0, 255, 204, 0.3);
        }

        /* Navigation dots */
        .nav-dots {
            position: fixed;
            right: clamp(1rem, 2vw, 2rem);
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: 8px;
            z-index: 100;
        }

        .nav-dot {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: rgba(255, 255, 255, 0.3);
            cursor: pointer;
            transition: all 0.3s ease;
        }

        .nav-dot.active {
            background: var(--accent-cyan);
            box-shadow: 0 0 10px var(--accent-cyan);
        }

        /* Progress bar */
        .progress-bar {
            position: fixed;
            top: 0;
            left: 0;
            height: 3px;
            background: linear-gradient(90deg, var(--accent-cyan), var(--accent-magenta));
            z-index: 101;
            transition: width 0.3s ease;
        }

        /* ===========================================
           SLIDE 1: TITLE SLIDE
           =========================================== */
        .title-slide {
            justify-content: center;
            align-items: center;
            text-align: center;
        }

        .title-slide h1 {
            font-family: var(--font-display);
            font-size: var(--title-size);
            font-weight: 700;
            line-height: 1.1;
            margin-bottom: var(--element-gap);
            background: linear-gradient(135deg, var(--text-primary) 0%, var(--accent-cyan) 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }

        .title-slide .subtitle {
            font-size: var(--h3-size);
            color: var(--text-secondary);
            margin-bottom: var(--content-gap);
            max-width: 800px;
        }

        .title-slide .source-badge {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 8px 16px;
            background: var(--bg-card);
            border: 1px solid var(--accent-cyan);
            border-radius: 50px;
            font-size: var(--small-size);
            color: var(--accent-cyan);
        }

        /* ===========================================
           SLIDE 2: PLATFORM OVERVIEW
           =========================================== */
        .stats-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 180px), 1fr));
            gap: var(--content-gap);
            margin-top: var(--content-gap);
        }

        .stat-card {
            background: var(--bg-card);
            border: 1px solid rgba(0, 255, 204, 0.2);
            border-radius: 12px;
            padding: clamp(1rem, 2vw, 1.5rem);
            text-align: center;
        }

        .stat-number {
            font-family: var(--font-display);
            font-size: clamp(1.5rem, 4vw, 2.5rem);
            font-weight: 700;
            color: var(--accent-cyan);
            text-shadow: 0 0 20px rgba(0, 255, 204, 0.5);
        }

        .stat-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-top: 4px;
        }

        /* ===========================================
           SLIDE 3: TOP 5 TRENDING REPOS - BAR CHART
           =========================================== */
        .bar-chart {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.5vw, 1rem);
            margin-top: var(--content-gap);
        }

        .bar-row {
            display: grid;
            grid-template-columns: 180px 1fr auto;
            align-items: center;
            gap: clamp(0.5rem, 1vw, 1rem);
        }

        .bar-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .bar-track {
            height: clamp(16px, 2.5vh, 28px);
            background: var(--bg-secondary);
            border-radius: 4px;
            overflow: hidden;
            position: relative;
        }

        .bar-fill {
            height: 100%;
            border-radius: 4px;
            transition: width 1s var(--ease-out-expo);
            position: relative;
        }

        .bar-fill.cyan { background: linear-gradient(90deg, var(--accent-cyan), rgba(0, 255, 204, 0.5)); }
        .bar-fill.magenta { background: linear-gradient(90deg, var(--accent-magenta), rgba(255, 0, 170, 0.5)); }
        .bar-fill.blue { background: linear-gradient(90deg, var(--accent-blue), rgba(67, 97, 238, 0.5)); }
        .bar-fill.orange { background: linear-gradient(90deg, var(--accent-orange), rgba(255, 107, 53, 0.5)); }
        .bar-fill.yellow { background: linear-gradient(90deg, var(--accent-yellow), rgba(255, 210, 63, 0.5)); }

        .bar-value {
            font-size: var(--small-size);
            font-weight: 600;
            min-width: 50px;
            text-align: right;
        }

        .repo-table {
            margin-top: var(--content-gap);
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 2px;
            background: var(--bg-secondary);
            border-radius: 8px;
            overflow: hidden;
        }

        .repo-table-header {
            background: var(--bg-card);
            padding: 8px 12px;
            font-size: var(--small-size);
            font-weight: 600;
            color: var(--accent-cyan);
        }

        .repo-table-cell {
            background: var(--bg-card);
            padding: 8px 12px;
            font-size: var(--small-size);
        }

        /* ===========================================
           SLIDE 4: LANGUAGE DISTRIBUTION - DONUT CHART
           =========================================== */
        .chart-container {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: var(--content-gap);
            align-items: center;
            margin-top: var(--content-gap);
        }

        .donut-chart {
            position: relative;
            width: clamp(180px, 25vw, 280px);
            height: clamp(180px, 25vw, 280px);
            margin: 0 auto;
        }

        .donut-chart svg {
            transform: rotate(-90deg);
        }

        .donut-chart circle {
            fill: none;
            stroke-width: 40;
        }

        .donut-center {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            text-align: center;
        }

        .donut-center .big-number {
            font-family: var(--font-display);
            font-size: clamp(1.5rem, 4vw, 2.5rem);
            font-weight: 700;
            color: var(--text-primary);
        }

        .donut-center .big-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
        }

        .legend {
            display: flex;
            flex-direction: column;
            gap: clamp(0.4rem, 1vh, 0.75rem);
        }

        .legend-item {
            display: flex;
            align-items: center;
            gap: 8px;
            font-size: var(--small-size);
        }

        .legend-dot {
            width: 12px;
            height: 12px;
            border-radius: 3px;
            flex-shrink: 0;
        }

        .legend-value {
            margin-left: auto;
            font-weight: 600;
        }

        /* ===========================================
           SLIDE 5: CATEGORY BREAKDOWN - TREEMAP STYLE
           =========================================== */
        .treemap {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            grid-template-rows: repeat(2, 1fr);
            gap: 4px;
            height: clamp(200px, 40vh, 350px);
            margin-top: var(--content-gap);
        }

        .treemap-cell {
            border-radius: 8px;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            padding: clamp(0.5rem, 1.5vw, 1rem);
            text-align: center;
            position: relative;
            overflow: hidden;
        }

        .treemap-cell.ai-agents {
            grid-column: span 2;
            grid-row: span 2;
            background: linear-gradient(135deg, var(--accent-cyan), rgba(0, 255, 204, 0.3));
        }

