            position: relative;
            height: clamp(200px, 40vh, 300px);
            margin-top: var(--content-gap);
            background: var(--bg-card);
            border-radius: 12px;
            padding: clamp(1rem, 2vw, 1.5rem);
        }

        .scatter-plot {
            position: relative;
            width: 100%;
            height: 100%;
        }

        .scatter-dot {
            position: absolute;
            width: clamp(20px, 3vw, 36px);
            height: clamp(20px, 3vw, 36px);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 10px;
            font-weight: 700;
            transform: translate(-50%, -50%);
            cursor: default;
            transition: transform 0.2s ease;
        }

        .scatter-dot:hover {
            transform: translate(-50%, -50%) scale(1.2);
            z-index: 10;
        }

        .scatter-dot.rank-1 { background: var(--accent-cyan); color: var(--bg-primary); }
        .scatter-dot.rank-2 { background: var(--accent-magenta); color: var(--bg-primary); }
        .scatter-dot.rank-8 { background: var(--accent-orange); color: var(--bg-primary); }
        .scatter-dot.other { background: var(--bg-secondary); color: var(--text-secondary); border: 1px solid rgba(255,255,255,0.2); }

        .axis-labels {
            position: absolute;
            font-size: var(--small-size);
            color: var(--text-secondary);
        }

        .axis-label-x { bottom: -30px; left: 50%; transform: translateX(-50%); }
        .axis-label-y { left: -30px; top: 50%; transform: translateY(-50%) rotate(-90deg); }

        .dot-labels {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 4px;
            margin-top: var(--content-gap);
        }

        .dot-label-item {
            display: flex;
            align-items: center;
            gap: 6px;
            font-size: var(--small-size);
        }

        .dot-label-item .dot {
            width: 10px;
            height: 10px;
            border-radius: 50%;
        }

        /* ===========================================
           SLIDE 8: KEY TAKEAWAYS
           =========================================== */
        .takeaways {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr));
            gap: var(--content-gap);
            margin-top: var(--content-gap);
        }

        .takeaway-card {
            background: var(--bg-card);
            border-radius: 12px;
            padding: clamp(1rem, 2vw, 1.5rem);
            border-left: 3px solid var(--accent-cyan);
        }

        .takeaway-card:nth-child(2) { border-left-color: var(--accent-magenta); }
        .takeaway-card:nth-child(3) { border-left-color: var(--accent-orange); }
        .takeaway-card:nth-child(4) { border-left-color: var(--accent-purple); }
        .takeaway-card:nth-child(5) { border-left-color: var(--accent-green); }

        .takeaway-card h4 {
            font-size: var(--body-size);
            margin-bottom: 8px;
            color: var(--text-primary);
        }

        .takeaway-card p {
            font-size: var(--small-size);
            color: var(--text-secondary);
        }

        .closing-footer {
            margin-top: var(--content-gap);
            text-align: center;
            font-size: var(--small-size);
            color: var(--text-secondary);
        }

        /* ===========================================
           RESPONSIVE BREAKPOINTS
           =========================================== */
        @media (max-height: 700px) {
            :root {
                --slide-padding: clamp(0.75rem, 3vw, 2rem);
                --content-gap: clamp(0.4rem, 1.5vw, 1rem);
            }
        }

        @media (max-height: 600px) {
            :root {
                --slide-padding: clamp(0.5rem, 2.5vw, 1.5rem);
                --content-gap: clamp(0.3rem, 1vw, 0.75rem);
            }
            .nav-dots { display: none; }
        }

        @media (max-width: 600px) {
            .chart-container { grid-template-columns: 1fr; }
            .ecosystem-grid { grid-template-columns: 1fr; }
            .bar-row { grid-template-columns: 120px 1fr auto; }
            .treemap { grid-template-columns: repeat(2, 1fr); grid-template-rows: auto; }
            .treemap-cell.ai-agents { grid-column: span 2; grid-row: span 1; }
        }

        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.2s !important;
            }
            html { scroll-behavior: auto; }
        }
